	\section{Preliminaries on random unitaries}
	\label{app:moments_random_unitaries}

	In this section, we review essential properties of random unitaries. 
	For an $n$-qubit system, let $d=2^n$ denote the dimension of the Hilbert space. 
	For an integer $r\geq1$, we define the representation $R_r(U)\coloneqq  U^{\otimes r}\otimes\overline U^{\otimes r}$, where $\overline U$ denotes entrywise complex conjugation in the computational basis. 
	By definition, $R_r(UV)=R_r(U)R_r(V)$.


	For a probability measure $\nu$ on $\mathrm{U}(d)$, its $r$-th moment operator is given by $M_r(\nu):= \mathbb E_{U\sim\nu}[R_r(U)]$. 
	By the triangle inequality, 
	\begin{equation}
		\left\|M_r(\nu)\right\|_{\mathrm{op}}
		\leq
		\mathbb E_{U\sim\nu}
		\left\|R_r(U)\right\|_{\mathrm{op}}
		=1.
		\label{eq:app-moment-contraction}
	\end{equation}
	The corresponding Haar moment is $P_{\mathrm H}^{(r)} := \bE_{U\sim \rm H}[R_r(U)]$, where $\rm H$ denotes the Haar measure.
	We can now define tensor-product expanders (TPEs) based on their distance to the Haar moment~\cite{Hastings2008QuantumTensorProduct, Brandao2016LocalRandomCircuits}:
	\begin{definition}[TPE $\lambda$-approximate unitary $r$-design]
		A unitary ensemble $\nu$ forms a TPE $\lambda$-approximate unitary $r$-design if 
		\begin{equation}
			\lambda_r(\nu) \coloneqq \left\|
			M_r(\nu)-P_{\mathrm H}^{(r)} \right\|_{\mathrm{op}}
			\le \lambda.
			\label{eq:app-nonhaar-contraction}
		\end{equation}
	\end{definition}

	A TPE can be directly converted into a multiplicative-error approximate design via the following bound:

	\begin{fact}[Comparison between TPE and multiplicative errors,
		{\cite[Lemma~4]{Brandao2016LocalRandomCircuits}}]
		\label{fact:TPE-multiplicative-comparison}
		Let $\nu$ be a unitary ensemble on a $d$-dimensional Hilbert space.
		If $\nu$ is a TPE $\lambda$-approximate unitary $r$-design, then it is a multiplicative $\epsilon$-approximate unitary $r$-design with
		\begin{equation}
			\epsilon\leq d^{2r}\lambda.
		\end{equation}
		Conversely, if $\nu$ is a multiplicative $\epsilon$-approximate unitary $r$-design, then it is a TPE $\lambda$-approximate unitary $r$-design with
		\begin{equation}
			\lambda\leq 2d^{r/2}\epsilon.
		\end{equation}
	\end{fact}





	\noindent Consequently, if $\lambda_r(\nu) = 0$, the ensemble $\nu$ forms an exact unitary $r$-design.

	For two probability measures $\mu$ and $\nu$ on $\mathrm{U}(d)$, let $\mu*\nu$ denote their convolution, the distribution of the product $UV$ for independent samples $U\sim\mu$ and $V\sim\nu$. 
	Let $\nu^{*T}$ denote the $T$-fold convolution, which represents the distribution of a product of $T$ independent samples drawn from $\nu$. 
	This repetition exponentially suppresses the TPE error~\cite[Eq.~(3)]{Brandao2016LocalRandomCircuits}:
	\begin{equation}
		\lambda_r(\nu^{*T})
		\leq
		\lambda_r(\nu)^T.
		\label{eq:app-gap-amplification}
	\end{equation}

	\section{Hadamard-diagonal ensembles}\label{app:spectral-Hadamard-diagonal}

	In this section, we prove the moment bound for the Hadamard--diagonal ensemble presented in Eqs.~\eqref{eq:ideal-fourier-gap} and \eqref{eq:HD-master-gap}. 
	Throughout this section, we index the computational basis by $G:=\mathbb{F}_2^m$ and denote the Hilbert space dimension by $d:=|G|=2^m$.

	\subsection{Ideal diagonal moments}

	Recall that a random unitary drawn from the ideal diagonal ensemble $\mathcal{D}_{\mathrm Z}$ takes the form
	\begin{equation}
		D_{\mathrm Z}
		=
		\sum_{x\in G}e^{i\theta_x}|x\rangle\langle x|,
		\qquad
		\theta_x\overset{\mathrm{iid}}{\sim}
		\mathrm{Unif}([0,2\pi)).
	\end{equation}
	Its $r$-th moment operator, $P_{\mathrm Z}^{(r)}:=M_r(\mathcal{D}_{\mathrm Z})$, acts as an orthogonal projector. Concretely, consider basis states labeled by $\bm x=(x_1,\ldots,x_r)$ and $\bm y=(y_1,\ldots,y_r)$ in $G^r$. The action of the moment operator is given by
	\begin{equation}
		P_{\mathrm Z}^{(r)}|\bm x,\bm y\rangle
		=
		\begin{cases}
			|\bm x,\bm y\rangle,
			& \bm y=\bm x_\sigma\text{ for some }\sigma\in S_r,\\
			0,
			& \text{otherwise},
		\end{cases}
		\label{eq:app-diagonal-projector-action}
	\end{equation}
	where $\bm x_\sigma:=(x_{\sigma(1)},\ldots,x_{\sigma(r)})$. Thus, $P_{\mathrm Z}^{(r)}$ acts as a projector that retains precisely the subspace spanned by basis vectors where $\bm x$ and $\bm y$ contain the same multiset of labels.

	Then, let $H_m:=H^{\otimes m}$ denote the $m$-qubit Hadamard transform, and define
	\begin{equation}
		W_r
		:=
		H_m^{\otimes r}\otimes\overline{H_m}^{\otimes r},
		\qquad
		P_{\mathrm X}^{(r)}
		:=
		W_rP_{\mathrm Z}^{(r)}W_r^\dagger.
		\label{eq:app-X-projector}
	\end{equation}
	Because $H_m$ is real and Hermitian, $W_r=W_r^\dagger$.
	Independence of the three diagonal unitaries in $U_{\mathrm{HD}}=D_3H_mD_2H_mD_1$ then gives
	\begin{align}
		M_r(\nu_{\mathrm{HD}})
		&=
		P_{\mathrm Z}^{(r)}W_rP_{\mathrm Z}^{(r)}
		W_rP_{\mathrm Z}^{(r)}
		\nonumber\\
		&=
		P_{\mathrm Z}^{(r)}P_{\mathrm X}^{(r)}P_{\mathrm Z}^{(r)}.
		\label{eq:app-ideal-HD-factorization}
	\end{align}

	While alternating random diagonal unitaries between two Hadamard-related bases is a well-established strategy for generating unitary designs~\cite{Nakata2017TimeIndependentHamiltonian}, the following theorem establishes a substantially tighter bound on the resulting TPE error.

	\begin{theorem}[TPE error of Hadamard--diagonal ensembles]
		\label{thm:app-fourier-gap}
		If $d\geq4r^4$, then
		\begin{equation}
			\left\|
			P_{\mathrm Z}^{(r)}P_{\mathrm X}^{(r)}P_{\mathrm Z}^{(r)}
			-P_{\mathrm H}^{(r)}
			\right\|_{\mathrm{op}}
			\leq
			\frac{9r^4}{d}.
			\label{eq:app-fourier-gap}
		\end{equation}
	\end{theorem}

	\begin{proof}
		\smallskip
		For $\bm x\in G^r$, define the size of its stabilizer under coordinate
		permutations by
		\begin{equation}
			\varsigma(\bm x)
			:=
			\left|
			\{\pi\in S_r:\bm x_\pi=\bm x\}
			\right|.
		\end{equation}

		Let $S_r$ denote the symmetric group on $[r]$.
		Let $\mathcal K$ be the auxiliary Hilbert space with orthonormal basis
		$\{|\bm x,\sigma\rangle:\bm x\in G^r,\ \sigma\in S_r\}$ and define
		\begin{equation}
			Q|\bm x,\sigma\rangle
			:=
			\varsigma(\bm x)^{-1/2}
			|\bm x,\bm x_\sigma\rangle.
			\label{eq:app-lifting-map}
		\end{equation}
		Every basis vector in $\operatorname{ran}P_{\mathrm Z}^{(r)}$ has
		exactly $\varsigma(\bm x)$ preimages under $Q$, and hence
		\begin{equation}
			QQ^\dagger=P_{\mathrm Z}^{(r)}.
			\label{eq:app-lifting-coisometry}
		\end{equation}

		Next, we define the operators
		\begin{equation}
			\mathsf A
			:=
			P_{\mathrm Z}^{(r)}W_rP_{\mathrm Z}^{(r)},
			\qquad
			\widehat{\mathsf A}
			:=
			Q^\dagger W_rQ.
			\label{eq:app-lifted-operators}
		\end{equation}
		Eq.~\eqref{eq:app-lifting-coisometry} implies that $Q^\dagger$ restricts to a unitary transformation from $\operatorname{ran}(P_{\mathrm Z}^{(r)})$ onto $\operatorname{ran}(Q^\dagger)$.
		Consequently, the operators are unitarily equivalent on their respective supports:
		\begin{equation}
			Q^\dagger
			\left(
			\mathsf A|_{\operatorname{ran}(P_{\mathrm Z}^{(r)})}
			\right)
			Q
			=
			\widehat{\mathsf A}|_{\operatorname{ran}(Q^\dagger)}.
			\label{eq:app-lifted-unitary-equivalence}
		\end{equation}
		Thus, $\mathsf A$ and $\widehat{\mathsf A}$ share exactly the same nonzero singular values.

		\smallskip
		\noindent\emph{Bounding off-diagonal blocks.}---
		View $\widehat{\mathsf A}$ as an $S_r\times S_r$ block matrix, with
		the rows and columns within each block indexed by
		$\bm x,\bm u\in G^r$. We have
		\begin{align}
			\langle\bm x,\sigma|
			\widehat{\mathsf A}
			|\bm u,\tau\rangle
			=
			\frac{d^{-r}}
			{\sqrt{\varsigma(\bm x)\varsigma(\bm u)}}
			(-1)^{
				\sum_{j=1}^r
				x_j\cdot
				[u_j+u_{(\tau\sigma^{-1})(j)}]
			}.
			\label{eq:app-lifted-Walsh-kernel}
		\end{align}
		Put $p:=\tau\sigma^{-1}$, let $c(p)$ be the number of cycles of $p$,
		and define
		\begin{equation}
			\ell(p):=r-c(p).
		\end{equation}
		Let $P_p$ permute the $r$ coordinates according to
		$(P_p\bm u)_j=u_{p(j)}$, and set
		$L_p:=I+P_p$ over $\bF_2$. The kernel of $L_p$ consists of the vectors
		that are constant on every cycle of $p$. Hence
		\begin{equation}
			\operatorname{rank}_{\bF_2}L_p=m \ell(p),
			\qquad
			|\ker L_p^{\mathsf T}|=d^{r-\ell(p)}
		\end{equation}
		when $L_p$ acts on $G^r$.

		Define a diagonal contraction $D$ and an unweighted Fourier block
		$K_p$ by
		\begin{equation}
			D|\bm x\rangle
			:=
			\varsigma(\bm x)^{-1/2}|\bm x\rangle,
			\qquad
			(K_p)_{\bm x,\bm u}
			:=
			d^{-r}(-1)^{\langle\bm x,L_p\bm u\rangle},
		\end{equation}
		where
		$\langle\bm x,\bm v\rangle:=\sum_jx_j\cdot v_j$ is the standard inner product over 
		$\bF_2$. Eq.~\eqref{eq:app-lifted-Walsh-kernel} gives
		$\widehat{\mathsf A}_{\sigma,\tau}=DK_pD$. Furthermore,
		\begin{align}
			(K_pK_p^\dagger)_{\bm x,\bm y}
			&=
			d^{-2r}
			\sum_{\bm u\in G^r}
			(-1)^{\langle\bm x-\bm y,L_p\bm u\rangle}
			\nonumber\\
			&=
			d^{-r}\,
			\mathbbm{1}
			\left\{
			L_p^{\mathsf T}(\bm x-\bm y)=0
			\right\}.
			\label{eq:app-Fourier-block-product}
		\end{align}
		This matrix is a direct sum of copies of
		$d^{-r}J_{d^{r-\ell(p)}}$, where $J_s$ denotes the $s\times s$
		all-ones matrix. Since $\|J_s\|_{\mathrm{op}}=s$, we obtain
		\begin{equation}
			\|K_p\|_{\mathrm{op}}^2=d^{-\ell(p)}.
		\end{equation}
		Using $\|D\|_{\mathrm{op}}\leq1$, we conclude that
		\begin{equation}
			\left\|
			\widehat{\mathsf A}_{\sigma,\tau}
			\right\|_{\mathrm{op}}
			\leq
			d^{-\ell(\tau\sigma^{-1})/2}.
			\label{eq:app-permutation-block-bound}
		\end{equation}

		\smallskip
		\noindent\emph{Approximation by a rank-$r!$ projector.}---
		Let $\mathsf B$ denote the block-diagonal part of
		$\widehat{\mathsf A}$. For a diagonal block, $\tau=\sigma$, so
		$p$ is the identity and $L_p=0$. Therefore
		\begin{equation}
			\langle\bm x,\sigma|
			\widehat{\mathsf A}
			|\bm u,\sigma\rangle
			=
			\frac{d^{-r}}
			{\sqrt{\varsigma(\bm x)\varsigma(\bm u)}}
			=
			a_{\bm x}a_{\bm u},
		\end{equation}
		where
		\begin{equation}
			a_{\bm x}
			:=
			d^{-r/2}\varsigma(\bm x)^{-1/2},
			\qquad
			\zeta
			:=
			\langle a,a\rangle
			=
			d^{-r}\sum_{\bm x\in G^r}\varsigma(\bm x)^{-1}.
		\end{equation}
		Thus every diagonal block equals $|a\rangle\langle a|$. Clearly
		$\zeta\leq1$. On the other hand, whenever the entries of $\bm x$ are
		pairwise distinct, $\varsigma(\bm x)=1$. There are
		$d(d-1)\cdots(d-r+1)$ such tuples, and therefore
		\begin{align}
			\zeta
			&\geq
			d^{-r}d(d-1)\cdots(d-r+1)
			\nonumber\\
			&=
			\prod_{j=0}^{r-1}
			\left(1-\frac jd\right)
			\geq
			1-\frac{\binom r2}{d}.
		\end{align}
		Let $|\widehat a\rangle:=\zeta^{-1/2}|a\rangle$ and define
		\begin{equation}
			P_0
			:=
			\bigoplus_{\sigma\in S_r}
			|\widehat a\rangle\langle\widehat a|.
		\end{equation}
		Then $P_0$ is an orthogonal projector of rank $r!$, and
		\begin{equation}
			\|\mathsf B-P_0\|_{\mathrm{op}}
			=
			1-\zeta
			\leq
			\frac{\binom r2}{d}.
			\label{eq:app-diagonal-block-approximation}
		\end{equation}

		For the block matrix $T=(T_{\sigma,\tau})_{\sigma,\tau\in S_r}$, define
		\begin{equation}
			R:=\max_{\sigma}\sum_{\tau}
			\|T_{\sigma,\tau}\|_{\mathrm{op}},
			\qquad
			C:=\max_{\tau}\sum_{\sigma}
			\|T_{\sigma,\tau}\|_{\mathrm{op}}.
		\end{equation}
		For any block vector \(v=(v_\tau)_{\tau\in S_r}\), the triangle
		inequality and Cauchy--Schwarz inequality give
		\begin{align}
			\|Tv\|^2
			&=
			\sum_{\sigma}
			\left\|
			\sum_{\tau}T_{\sigma,\tau}v_\tau
			\right\|^2
			\nonumber\\
			&\leq
			\sum_{\sigma}
			\left(
			\sum_{\tau}
			\|T_{\sigma,\tau}\|_{\mathrm{op}}\,
			\|v_\tau\|
			\right)^2
			\nonumber\\
			&\leq
			R\sum_{\sigma,\tau}
			\|T_{\sigma,\tau}\|_{\mathrm{op}}\,
			\|v_\tau\|^2
			\leq
			RC\|v\|^2.
		\end{align}
		Taking the supremum over \(v\neq0\) therefore yields
		\begin{equation}
			\|T\|_{\mathrm{op}}
			\leq
			\sqrt{RC}
			=
			\left(
			\max_{\sigma}\sum_{\tau}
			\|T_{\sigma,\tau}\|_{\mathrm{op}}
			\right)^{1/2}
			\left(
			\max_{\tau}\sum_{\sigma}
			\|T_{\sigma,\tau}\|_{\mathrm{op}}
			\right)^{1/2}.
		\end{equation}



		Applying this to $\widehat{\mathsf A}-\mathsf B$ and using
		Eq.~\eqref{eq:app-permutation-block-bound}, both block sums are bounded by
		\begin{equation}
			\sum_{p\neq e}d^{-\ell(p)/2}.
		\end{equation}
		A permutation satisfying $\ell(p)=\ell$ can be expressed as a product
		of $\ell$ transpositions. Hence the number of such permutations is at
		most $\binom r2^\ell\leq r^{2\ell}$. Because
		$d\geq4r^4$, we have $r^2/\sqrt d\leq1/2$, and therefore
		\begin{align}
			\|\widehat{\mathsf A}-\mathsf B\|_{\mathrm{op}}
			&\leq
			\sum_{p\neq e}d^{-\ell(p)/2}
			\nonumber\\
			&\leq
			\sum_{\ell\geq1}
			\left(\frac{r^2}{\sqrt d}\right)^\ell
			\leq
			\frac{2r^2}{\sqrt d}.
			\label{eq:app-offdiagonal-block-bound}
		\end{align}
		Combining Eqs.~\eqref{eq:app-diagonal-block-approximation} and
		\eqref{eq:app-offdiagonal-block-bound}, we find
		\begin{equation}
			\|\widehat{\mathsf A}-P_0\|_{\mathrm{op}}
			\leq
			\eta
			:=
			\frac{2r^2}{\sqrt d}
			+
			\frac{\binom r2}{d}.
			\label{eq:app-lifted-rank-approximation}
		\end{equation}

		\smallskip
		\noindent\emph{Identifying the Haar sector.}---
		For \(d\ge r\), the Haar moment projector has rank
		\begin{equation}
			\operatorname{rank}P_{\mathrm H}^{(r)}=r!
		\end{equation}
		by Schur--Weyl duality~\cite[Theorem~9 and Propositions~11 and~25]{Mele2024HaarTools}.
		If $v\in\operatorname{ran}P_{\mathrm H}^{(r)}$, then
		$R_r(U)v=v$ for every $U$. Averaging over diagonal unitaries gives
		$P_{\mathrm Z}^{(r)}v=v$, while taking $U=H_m$ gives $W_rv=v$.
		Consequently,
		\begin{equation}
			\mathsf Av
			=
			P_{\mathrm Z}^{(r)}W_rP_{\mathrm Z}^{(r)}v
			=v.
		\end{equation}
		Moreover, $W_r=W_r^\dagger$ implies
		$\mathsf A=\mathsf A^\dagger$. Thus the orthogonal complement of the
		Haar-invariant subspace is invariant under $\mathsf A$, and
		\begin{equation}
			\mathsf A
			=
			I_{\operatorname{ran}P_{\mathrm H}^{(r)}}
			\oplus
			\mathsf A_\perp.
			\label{eq:app-A-Haar-decomposition}
		\end{equation}

		Let $s_j(T)$ denote the $j$-th largest singular value of $T$. The
		variational characterization
		\begin{equation}
			s_{L+1}(T)
			=
			\inf_{\operatorname{rank}R\leq L}
			\|T-R\|_{\mathrm{op}},
		\end{equation}
		together with Eqs.~\eqref{eq:app-lifted-unitary-equivalence} and
		\eqref{eq:app-lifted-rank-approximation}, gives
		\begin{equation}
			\|\mathsf A_\perp\|_{\mathrm{op}}
			=
			s_{r!+1}(\mathsf A)
			=
			s_{r!+1}(\widehat{\mathsf A})
			\leq
			\eta.
			\label{eq:app-A-perp-bound}
		\end{equation}
		Finally, using $W_r^\dagger=W_r$,
		\begin{equation}
			P_{\mathrm Z}^{(r)}P_{\mathrm X}^{(r)}P_{\mathrm Z}^{(r)}
			=
			P_{\mathrm Z}^{(r)}W_rP_{\mathrm Z}^{(r)}W_r
			P_{\mathrm Z}^{(r)}
			=
			\mathsf A^2.
		\end{equation}
		Eq.~\eqref{eq:app-A-Haar-decomposition} therefore yields
		\begin{align}
			\left\|
			P_{\mathrm Z}^{(r)}P_{\mathrm X}^{(r)}P_{\mathrm Z}^{(r)}
			-P_{\mathrm H}^{(r)}
			\right\|_{\mathrm{op}}
			&=
			\|\mathsf A^2-P_{\mathrm H}^{(r)}\|_{\mathrm{op}}
			\nonumber\\
			&=
			\|\mathsf A_\perp^2\|_{\mathrm{op}}
			=
			\|\mathsf A_\perp\|_{\mathrm{op}}^2
			\leq
			\eta^2.
		\end{align}
		Because $\binom r2\leq r^2$ and $d^{-1}\leq d^{-1/2}$, $\eta \leq \frac{3r^2}{\sqrt d}$, which proves Eq.~\eqref{eq:app-fourier-gap}.
	\end{proof}




	\subsection{Stability under diagonal approximation}
	We now examine the stability of the Hadamard-diagonal construction when the ideal diagonal ensemble is replaced by an arbitrary ensemble $\mathcal{D}_m$. Define
	\begin{equation}
		\widetilde P_{\mathrm Z}^{(r)}
		:=
		M_r(\cD_m),
		\qquad
		\epsilon_{\mathrm{diag}}(r)
		:=
		\left\|
		\widetilde P_{\mathrm Z}^{(r)}-P_{\mathrm Z}^{(r)}
		\right\|_{\mathrm{op}},
		\label{eq:app-diagonal-approximation-error}
	\end{equation}
	and
	\begin{equation}
		\widetilde P_{\mathrm X}^{(r)} :=
		W_r\widetilde P_{\mathrm Z}^{(r)}W_r^\dagger.
	\end{equation}
	Let $\nu_{\mathrm{HD}}^{(m)}$ denote the ensemble in which the three
	diagonal layers of the Hadamard--diagonal block are sampled
	independently from $\cD_m$.
	Then, we have
	\begin{equation}
		M_r\left(\nu_{\mathrm{HD}}^{(m)}\right) =
		\widetilde P_{\mathrm Z}^{(r)}
		\widetilde P_{\mathrm X}^{(r)}
		\widetilde P_{\mathrm Z}^{(r)},
		\label{eq:app-implemented-HD-factorization}
	\end{equation}
	The following lemma establishes that the resulting TPE error degrades at most linearly with the diagonal approximation error.

	\begin{lemma}[Stability under diagonal approximation]
		\label{lem:app-HD-perturbation}
		For every $r\geq1$ satisfying $d=2^m\geq4r^4$,
		\begin{equation}
			\lambda_r\left(\nu_{\mathrm{HD}}^{(m)}\right)
			\leq
			\frac{9r^4}{2^m}
			+
			3\epsilon_{\mathrm{diag}}(r).
			\label{eq:app-HD-master-gap}
		\end{equation}
	\end{lemma}

	\begin{proof}
		By the unitary invariance of the operator norm,
		\begin{equation}
			\left\|
			\widetilde P_{\mathrm X}^{(r)}-P_{\mathrm X}^{(r)}
			\right\|_{\mathrm{op}}
			=
			\epsilon_{\mathrm{diag}}(r).
		\end{equation}
		Moreover, 
		\begin{align}
			\widetilde P_{\mathrm Z}^{(r)}
			\widetilde P_{\mathrm X}^{(r)}
			\widetilde P_{\mathrm Z}^{(r)}
			-
			P_{\mathrm Z}^{(r)}P_{\mathrm X}^{(r)}P_{\mathrm Z}^{(r)} =
			\left(\widetilde P_{\mathrm Z}^{(r)}-P_{\mathrm Z}^{(r)}\right)
			\widetilde P_{\mathrm X}^{(r)}
			\widetilde P_{\mathrm Z}^{(r)}
			+
			P_{\mathrm Z}^{(r)}
			\left(\widetilde P_{\mathrm X}^{(r)}-P_{\mathrm X}^{(r)}\right)
			\widetilde P_{\mathrm Z}^{(r)} +
			P_{\mathrm Z}^{(r)}P_{\mathrm X}^{(r)}
			\left(\widetilde P_{\mathrm Z}^{(r)}-P_{\mathrm Z}^{(r)}\right).
		\end{align}
		Notice that all ideal and approximate moment operators have operator norms bounded by $1$. 
		Therefore,
		\begin{equation}
			\left\|
			M_r\left(\nu_{\mathrm{HD}}^{(m)}\right)
			-
			P_{\mathrm Z}^{(r)}P_{\mathrm X}^{(r)}P_{\mathrm Z}^{(r)}
			\right\|_{\mathrm{op}}
			\leq
			3\epsilon_{\mathrm{diag}}(r).
		\end{equation}
		Combining this estimate with
		Theorem~\ref{thm:app-fourier-gap} proves
		Eq.~\eqref{eq:app-HD-master-gap}.
	\end{proof}

